package com.example.agendapersonal.ui;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;
import com.example.agendapersonal.R;import com.example.agendapersonal.respaldo.GestorRespaldo;import com.example.agendapersonal.sync.CoordinadorSync;
import java.time.LocalDate;import java.util.Arrays;

public class RespaldoActivity extends com.example.agendapersonal.ui.ActividadTematica {
    private TextView estado;private boolean trabajando;private GestorRespaldo.Preparada preparada;
    @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_respaldo);estado=findViewById(R.id.estadoRespaldo);findViewById(R.id.crearRespaldo).setOnClickListener(v->elegirDestino(71));findViewById(R.id.restaurarRespaldo).setOnClickListener(v->{if(trabajando)return;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),72);});findViewById(R.id.exportarAnterior).setOnClickListener(v->elegirDestino(73));findViewById(R.id.volverRespaldo).setOnClickListener(v->finish());if(b!=null)estado.setText("Si la operación anterior fue interrumpida, volvé a elegir el archivo. La contraseña no se conserva.");actualizarAnterior();}
    private void actualizarAnterior(){findViewById(R.id.exportarAnterior).setEnabled(!trabajando&&GestorRespaldo.hayAnterior(this));}
    private void elegirDestino(int codigo){if(trabajando)return;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/octet-stream").putExtra(Intent.EXTRA_TITLE,"AgendaPersonal-"+(codigo==73?"estado-anterior-":"")+LocalDate.now()+".agendabak"),codigo);}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;if(request==71||request==72||request==73)password(request,data.getData());}
    private void password(int request,Uri uri){boolean leer=request==72;LinearLayout campos=new LinearLayout(this);campos.setOrientation(LinearLayout.VERTICAL);int pad=EstiloApp.dp(this,20);campos.setPadding(pad,pad,pad,pad);TextView ayuda=new TextView(this);ayuda.setText(leer?"Ingresá la contraseña que elegiste al crear esta copia.":"Elegí una contraseña de al menos 8 caracteres para proteger la copia. Guardala en un lugar seguro: si la olvidás, no podremos abrir ese archivo. No tiene que ser la contraseña de Supabase.");campos.addView(ayuda);EditText primera=new EditText(this),segunda=new EditText(this);primera.setHint("Contraseña de la copia");segunda.setHint("Repetir contraseña");for(EditText e:new EditText[]{primera,segunda}){e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);e.setSaveEnabled(false);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);}campos.addView(primera);if(!leer)campos.addView(segunda);AlertDialog d=new AlertDialog.Builder(this).setTitle(leer?"Abrir copia completa":"Proteger copia completa").setView(campos).setNegativeButton("Cancelar",null).setPositiveButton(leer?"Comprobar":"Guardar",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{String a=primera.getText().toString();if(a.length()<8){primera.setError("Usá al menos 8 caracteres");return;}if(!leer&&!a.equals(segunda.getText().toString())){segunda.setError("Las contraseñas no coinciden");return;}char[] secreto=a.toCharArray();primera.setText("");segunda.setText("");d.dismiss();operar(request,uri,secreto);}));d.show();}
    private void ocupado(boolean valor,String texto){trabajando=valor;estado.setText(texto);findViewById(R.id.crearRespaldo).setEnabled(!valor);findViewById(R.id.restaurarRespaldo).setEnabled(!valor);findViewById(R.id.volverRespaldo).setEnabled(!valor);actualizarAnterior();}
    private void operar(int codigo,Uri uri,char[] secreto){ocupado(true,codigo==72?"Comprobando contraseña, integridad y compatibilidad…":"Creando copia completa protegida…");CoordinadorSync.de(this).ejecutar(()->{try{if(codigo==72){GestorRespaldo.Preparada p=GestorRespaldo.preparar(this,uri,secreto);runOnUiThread(()->{if(isFinishing()||isDestroyed()){p.close();return;}preparada=p;ocupado(false,"Copia válida. Revisá el resumen antes de restaurar.");confirmar();});}else{if(codigo==71)GestorRespaldo.exportar(this,uri,secreto);else GestorRespaldo.exportarAnterior(this,uri,secreto);informar("Copia completa guardada en la ubicación elegida. Conservá el archivo y su contraseña para poder recuperarla.");}}catch(Exception e){informar("No se completó la operación. "+detalle(e));}finally{Arrays.fill(secreto,'\0');}});}
    private void confirmar(){GestorRespaldo.Preparada p=preparada;new AlertDialog.Builder(this).setTitle("Restaurar esta copia").setMessage(p.resumen()).setNegativeButton("Conservar datos actuales",(d,w)->limpiar()).setOnCancelListener(d->limpiar()).setPositiveButton("Restaurar copia",(d,w)->{ocupado(true,"Guardando el estado actual y restaurando la copia…");CoordinadorSync sync=CoordinadorSync.de(this);sync.ejecutar(()->{boolean automatico=sync.automatico();try{sync.automatico(false);GestorRespaldo.restaurar(this,p);runOnUiThread(()->{limpiar();if(isDestroyed())return;Toast.makeText(this,"Copia restaurada. Volvé a conectar Supabase para reanudar la sincronización.",Toast.LENGTH_LONG).show();startActivity(new Intent(this,com.example.agendapersonal.MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();});}catch(Exception e){if(automatico&&!GestorRespaldo.configuracionPendiente(this))sync.automatico(true);informar("La restauración no se completó. "+detalle(e));runOnUiThread(this::limpiar);}});}).show();}
    private void limpiar(){if(preparada!=null){preparada.close();preparada=null;}}
    private static String detalle(Exception e){if(e instanceof android.database.sqlite.SQLiteDatabaseLockedException)return "La agenda estaba ocupada. Volvé a intentar cuando termine la operación actual.";if(e instanceof java.io.IOException||e instanceof IllegalArgumentException)return e.getMessage()==null?"Revisá el archivo y el espacio disponible.":e.getMessage();return "El archivo no es compatible o no hay espacio suficiente. Los datos no confirmados se conservan.";}
    private void informar(String s){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())ocupado(false,s);});}
    @Override public void onBackPressed(){if(trabajando){Toast.makeText(this,"Esperá a que termine la operación",Toast.LENGTH_SHORT).show();return;}super.onBackPressed();}
    @Override protected void onDestroy(){if(!trabajando)limpiar();super.onDestroy();}
}
